.DamagePopupsRoot {
    width: 100%;
    height: 100%;
    flow-children: none;
    overflow: noclip;
}

.DamagePopupsLayer {
    width: 100%;
    height: 100%;
    flow-children: none;
    overflow: noclip;
}

.DamagePopup {
    font-family: Radiance, FZKai-Z03, FZKai-Z03S;
    font-size: 22px;
    font-weight: bold;
    color: #ffffff;
    text-shadow: 0px 0px 2px 3.0 #000000aa;
    opacity: 0.0;
    transition-property: transform, opacity;
    transition-duration: 0.85s;
    transition-timing-function: ease-out;
}

.DamagePopup--Active {
    opacity: 1.0;
    transform: translate3d(0px, -40px, 0px) scale3d(1.05, 1.05, 1.0);
}

.DamagePopup--Crit {
    color: #ff4d4d;
    font-size: 26px;
}

.DamagePopup--Enhance {
    color: #4d8bff;
}

.DamagePopup--Heal {
    color: #5cff7a;
}

.DamagePopup--Gold {
    color: #ffd25a;
}

.DamagePopup--Block {
    color: #9fd1ff;
}
